test("roles inherit grants from their parent chain (ACCESS-284)",()=>{
  const dir={"report-reader":{grants:["report:download"]},auditor:{grants:[],parent:"report-reader"},nested:{grants:[],parent:"auditor"}};
  assert.equal(downloadReport({id:"u",roles:["auditor"],denied:[]},"r1",dir,reports).status,200);
  assert.equal(downloadReport({id:"u",roles:["nested"],denied:[]},"r1",dir,reports).status,200);
  assert.equal(downloadReport({id:"u",roles:["auditor"],denied:["report:download"]},"r1",dir,reports).status,403);
});
test("parent cycles and dangling parents do not hang or grant access",()=>{
  const dir={a:{grants:[],parent:"b"},b:{grants:[],parent:"a"},c:{grants:[],parent:"missing"}};
  assert.equal(allows({id:"u",roles:["a","c"],denied:[]},"report:download",dir),false);
});
EOF
